hand_value <- function(cards) {
  total <- 0
  aces <- 0
  for (card in cards) {
    if (card == "A") {
      total <- total + 11
      aces <- aces + 1
    } else if (card %in% c("J", "Q", "K")) {
      total <- total + 10
    } else {
      total <- total + as.numeric(card)
    }
  }
  while (total > 21 && aces > 0) {
    total <- total - 10
    aces <- aces - 1
  }
  total
}
